package com.lth.ecommerceagent.freight;
import java.math.BigDecimal; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus; import com.lth.ecommerceagent.tenant.TenantContext;
@RestController @RequestMapping("/api/freight-rules") public class StoreFreightRuleController { private final StoreFreightRuleRepository repo; public StoreFreightRuleController(StoreFreightRuleRepository r){repo=r;}
 public record Rule(String province,BigDecimal fee){} public record SaveRequest(List<Rule> rules,BigDecimal defaultFee,Boolean freeShipping){}
 @GetMapping @PreAuthorize("hasRole('SUPER_ADMIN') or hasRole('OWNER')") public Map<String,Object> get(){var p=TenantContext.principal();if(p==null||p.companyId()==null||p.storeId()==null)return Map.of("rules",List.of());return Map.of("rules",repo.findByStoreIdAndCompanyIdOrderByProvince(p.storeId(),p.companyId()).stream().map(x->new Rule(x.getProvince(),x.getFee())).toList());}
 @PutMapping @PreAuthorize("hasRole('OWNER')") public Map<String,Object> save(@RequestBody SaveRequest r){var p=TenantContext.principal();if(p==null||p.companyId()==null||p.storeId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"请先选择店铺");if(r.rules()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"运费规则不能为空");repo.deleteByStoreIdAndCompanyId(p.storeId(),p.companyId());for(var x:r.rules()){if(x.province()==null||x.province().isBlank()||x.fee()==null||x.fee().signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"省份和运费必须有效");var rule=new StoreFreightRule();rule.setProvince(x.province().trim());rule.setFee(x.fee());repo.save(rule);}return get();}}
